function handler(span) {
  const meta = span.metadata || {};
  const trajectory = (span.metadata && span.metadata.trajectory) || [];
  const tools = trajectory.map((s) => s.tool).filter(Boolean).join(' -> ');
  const finding = meta.finding || {};
  const question = span.input || meta.question || '';
  const answer = finding.answer || meta.answer || '';
  const grounded = meta['obj/grounded_accuracy'];
  return [
    `question: ${question}`,
    `tool sequence: ${tools || '(none)'}`,
    `final answer: ${answer}`,
    `obj/grounded_accuracy: ${grounded}`,
  ].join('\n');
}
